#include <jsd/project_runtime.hpp>
#include <jsd/project_capture.hpp>
#include <iostream>
using namespace jsd;using namespace jsd::project;
int main(){unsigned count=0;auto check=[&](bool ok,const char*name){if(!ok)throw std::runtime_error(name);++count;std::cout<<"PASS "<<name<<'\n';};auto temp=std::filesystem::temp_directory_path()/("jsd-project-tests-"+std::to_string(std::chrono::steady_clock::now().time_since_epoch().count()));try{
 check(std::abs(scalarKeys(Json::array({{0,0,"smooth"},{1,1}}),.25f,-1)-.15625f)<1e-6f,"smooth environment property interpolation");
 check(scalarKeys(Json::array({{0,2,"step"},{1,7}}),.9f,-1)==2&&std::abs(scalarKeys(Json::array({{0,0},{1,1}}),.25f,-1)-.25f)<1e-6f,"step and linear environment property interpolation");
 std::filesystem::create_directories(temp);auto d=Document::example();auto box=d.objects.front().id;
 d.terrain.enabled=true;d.terrain.generator="waves";auto base=d.terrain.height(7,8);d.terrain.brush(7,8,12,4,0);check(d.terrain.height(7,8)>base+3,"sculpt raises procedural terrain");auto raised=d.terrain.height(7,8);d.terrain.brush(7,8,12,2,1);check(d.terrain.height(7,8)<raised,"lower brush lowers terrain");d.terrain.brush(7,8,12,1,3,12);check(std::abs(d.terrain.height(7,8)-12)<1,"flatten targets world height");d.terrain.brush(7,8,12,.7f,4,0,{.3,.4,.5,1});check(d.terrain.color(7,8).r<.6f,"paint stores terrain tint");auto t=d.terrain;auto rev=t.revision;t.resize(257);check(std::abs(t.height(7,8)-d.terrain.height(7,8))<.5f&&t.revision!=rev,"grid resize resamples sculpt and invalidates cache");auto loadedTerrain=TerrainData::fromJson(t.json());check(loadedTerrain.json()==t.json()&&loadedTerrain.revision!=t.revision,"lossless terrain data and fresh runtime revision");
 History history;history.begin(d,"Sculpt");auto original=d.terrain.json();d.terrain.brush(5,5,10,2,0);history.commit(d);check(history.undo(d)&&d.terrain.json()==original,"terrain stroke undo");check(history.redo(d)&&d.terrain.json()!=original,"terrain stroke redo");
 writeMesh(primitive(0),temp/"shared.jsdmesh");d.meshAssets["box"]=(temp/"shared.jsdmesh").string();auto id=d.add(Kind::Mesh,"Shared");auto*o=d.find(id);o->mesh={};o->meshRef="box";o->sharedMesh=readMesh(d.meshAssets.at("box"));o->materialOverride=0;check(o->sharedMesh==readMesh(d.meshAssets.at("box")),"immutable mesh resource cache");Object unique=*o;makeUnique(unique);unique.mesh.vertices[0].position.x+=2;check(!unique.sharedMesh&&geometry(unique).vertices[0].position.x!=geometry(*o).vertices[0].position.x,"instance geometry uses copy on edit");
 auto a=o->transform,b=a;b.position.x=3;o->motion.keys={{0,a,1},{2,b,1}};o->motion.relative=true;o->transform.position.x=10;auto expected=matrix(evaluate(*o,1));writeClip(o->motion.keys,temp/"move.jsdclip");o->motion.sharedKeys=readClip(temp/"move.jsdclip");o->motion.clipFile=(temp/"move.jsdclip").string();o->motion.keys.clear();check(std::abs(evaluate(*o,1).position.x-11.5f)<.001f,"relative shared animation offsets authored transform");editableKeys(*o);auto edited=matrix(evaluate(*o,1));float error=0;for(unsigned i=0;i<16;i++)error+=std::abs(expected.m[i]-edited.m[i]);check(error<.001f&&!o->motion.relative&&o->motion.clipFile.empty(),"making captured track editable preserves motion");
 writeClip(o->motion.keys,temp/"move.jsdclip");o->motion.clipFile=(temp/"move.jsdclip").string();o->motion.sharedKeys=readClip(temp/"move.jsdclip");o->motion.keys.clear();
 Image image{1,1,4,{100,130,150,255}};writePng(image,temp/"map.png");d.materials[0].albedo=(temp/"map.png").string();auto overlay=d.add(Kind::Overlay,"Image");d.find(overlay)->components["overlay"]={{"type","image"},{"file",(temp/"map.png").string()},{"rect",{0,0,64,64}}};atomicWrite(temp/"license.txt","Attribution");d.projectInfo["licenses"]=Json::array({{{"file",(temp/"license.txt").string()}}});d.save(temp/"first/scene.jsdproject");auto one=Document::load(temp/"first/scene.jsdproject");check(one.terrain.json()==d.terrain.json()&&geometry(*one.find(id)).vertices.size()==8,"engine project loads terrain and shared assets");d.save(temp/"second/scene.jsdproject");std::filesystem::remove_all(temp/"first");std::filesystem::remove(temp/"map.png");std::filesystem::remove(temp/"shared.jsdmesh");std::filesystem::remove(temp/"move.jsdclip");std::filesystem::remove(temp/"license.txt");auto relocated=Document::load(temp/"second/scene.jsdproject");check(std::filesystem::exists(relocated.materials[0].albedo)&&std::filesystem::exists(relocated.find(overlay)->components["overlay"]["file"].get<std::string>())&&std::filesystem::exists(relocated.find(id)->motion.clipFile),"Save As rebases every runtime asset");check(std::filesystem::exists(relocated.projectInfo["licenses"][0]["file"].get<std::string>()),"portable attribution resources");
 Document physics;physics.materials.push_back(Surface{});auto floor=physics.add(Kind::Collider,"Floor",primitive(0));physics.find(floor)->physics.mode=1;physics.find(floor)->transform.scale={10,1,10};physics.find(floor)->transform.position.y=-.5;auto body=physics.add(Kind::Mesh,"Body");physics.find(body)->sharedMesh=relocated.find(id)->sharedMesh;physics.find(body)->meshRef="box";physics.find(body)->transform.position.y=3;physics.find(body)->physics.mode=3;Simulation simulation;simulation.enabled=true;simulation.seek(physics,2);check(rf::transformPoint(simulation.pose().at(body),{}).y>.48f,"shared geometry collides with dedicated collider nodes");
 auto bad=d;bad.find(box)->transform.quaternion=Quat{0,0,0,0};bool rejected=false;try{bad.validate();}catch(...){rejected=true;}check(rejected,"invalid quaternion rejected");bad=d;bad.terrain.resolution=2049;rejected=false;try{bad.validate();}catch(...){rejected=true;}check(rejected,"oversized terrain grid rejected");
 auto root=d.add(Kind::Empty,"Hidden root");d.find(root)->visible=false;d.find(id)->parent=root;check(!active(d,*d.find(id),1),"parent visibility applies to child objects");
 d.materials[0].engine={{"surface",1},{"surfaceSeed",98217},{"surfaceWorld",false},{"wetness",.7f},{"dust",.1f},{"sheen",.2f},{"anisotropy",.6f}};
 d.environment["reflectionProbes"]=Json::array({{{"id",42},{"position",{0,2,0}},{"halfExtent",{4,3,4}},{"refreshFrames",90}}});
 d.environment["fogVolumes"]=Json::array({{{"position",{0,2,0}},{"halfExtent",{1,1,1}},{"density",.03},{"emission",{.2,.03,0,1}}}});
 auto recipes=Document::fromJson(d.json());
 {
  ProjectCapture capture(temp/"spotlight.jsdproject");gfx::Light l;l.type=gfx::LightType::Spot;l.position={2,4,6};l.direction=rf::normalized(V3{-1,-2,1});l.falloff=gfx::LightFalloff::InverseSquare;l.intensity=1200;l.radius=18;l.innerCone=.3f;l.outerCone=.8f;l.sourceRadiusMetres=.24f;l.castShadow=true;l.shadowId=1;
  capture.frame(0);capture.lightSubmitted(l);capture.frame(1);l.direction=rf::normalized(V3{1,-2,1});capture.lightSubmitted(l);capture.finish();
  auto loaded=Document::load(temp/"spotlight.jsdproject");check(loaded.name=="Captured scene"&&loaded.objects.size()==3,"capture uses generic scene groups");auto light=std::find_if(loaded.objects.begin(),loaded.objects.end(),[](auto&o){return o.kind==Kind::SpotLight;});
  check(light!=loaded.objects.end()&&light->lumens==1200&&light->components.value("photometricCandela",false)&&light->components.value("castShadow",false)&&std::abs(light->components.value("sourceRadiusMetres",0.f)-.24f)<.00001f&&std::abs(light->outerCone-.8f)<.00001f,"exported spotlights preserve candela, cone and finite-emitter shadow settings");
  auto transform=matrix(evaluate(*light,1));auto direction=rf::normalized(rf::transformVector(transform,{0,0,-1}));
  check(rf::dot(direction,l.direction)>.9999f,"spotlight direction animation survives capture and portable project loading");
 }
 check(recipes.environment==d.environment,"probe and bounded-fog definitions roundtrip through projects");
 check(recipes.materials[0].engine==d.materials[0].engine,"procedural recipes retain seed and coordinate frame in project files");
 auto invalid=recipes;invalid.materials[0].engine["surface"]=99;rejected=false;try{invalid.validate();}catch(...){rejected=true;}
 check(rejected,"unknown procedural surface recipe is rejected");
 invalid=recipes;invalid.materials[0].engine["wetness"]=1.2f;rejected=false;try{invalid.validate();}catch(...){rejected=true;}check(rejected,"invalid layer weight is rejected before rendering");
 invalid=recipes;invalid.environment["fogVolumes"][0]["density"]=-1;rejected=false;try{invalid.validate();}catch(...){rejected=true;}check(rejected,"invalid volumetric density is rejected before rendering");
 std::filesystem::remove_all(temp);std::cout<<count<<" project checks passed\n";return 0;
 }catch(const std::exception&e){std::cerr<<"FAILED "<<e.what()<<'\n';std::filesystem::remove_all(temp);return 1;}}
